    'tour.help': 'Как устроен раздел',
    'tour.home.goal.title': 'Твоя цель',
    'tour.home.goal.text': 'До какого уровня хочешь дойти? Выбери — и дорожка покажет весь путь до него.',
    'tour.home.skills.title': 'Сильные и слабые стороны',
    'tour.home.skills.text': 'Проценты считаются по заданиям в практике: сколько ответов верны с первой попытки. Чем больше заданий, тем точнее картина.',
    'tour.home.recommend.title': 'Что сделать сегодня',
    'tour.home.recommend.text': 'Одна подсказка по твоим данным: горящая домашка, слабый навык или давно не было практики.',
    'tour.home.schedule.title': 'Расписание',
    'tour.home.schedule.text': 'Занятия на неделю вперёд. Нажми на урок, чтобы открыть его.',
    // Приветствие туров разделов (вид «Главной»): «Это раздел» и крупно — имя раздела из меню.
    'tour.intro.title': 'Это раздел',
    'tour.intro.cta': 'Показать',
    'tour.intro.skip': 'Пропустить',
    'tour.practice.intro.text':
      'Тренажёры на все навыки и мини-игры — занимайся сам, в своём темпе. Покажем за минуту, что где лежит.',
    'tour.learn.intro.text':
      'Повторяй то, что прошли на уроках: карта уровней от A0 до C1, внутри — уроки по порядку. Покажем, как тут ходить.',
    'tour.lessons.intro.text':
      'Здесь занятия с преподавателем: ближайший урок и календарь всех встреч. Покажем, где что.',
    'tour.hw.intro.text':
      'Задания от преподавателя: открываешь работу, прикрепляешь ответ и отправляешь на проверку. Покажем, как это делается.',
    'tour.vocab.intro.text':
      'Слова по уровням и по темам, плюс твой личный словарь — туда попадают слова, которые сохраняешь в заданиях. Покажем за минуту.',
    'tour.plan.intro.text': 'План по дням до вашей цели: что сделать сегодня и на неделе. Покажем, как им пользоваться.',
    'tour.practice.skills.title': 'Пять разделов',
    'tour.practice.skills.text':
      'Аудирование, чтение, письмо, говорение и грамматика. У каждого раздела свой цвет — нажми, и под ним соберутся его тренажёры.',
    'tour.practice.levels.title': 'Уровень материалов',
    'tour.practice.levels.text':
      'Подбирает книжки, песни, ситуации и юниты грамматики под выбранный уровень. «Все» — показать всё.',
    'tour.learn.map.title': 'Карта уровней',
    'tour.learn.map.text':
      'Остров — весь путь от A0 до C1. Каждый город на нём — уровень, карта прокручивается снизу вверх.',
    'tour.learn.current.title': 'Твой уровень',
    'tour.learn.current.text':
      'Карта открывается здесь. Внутри города — тропа уроков: проходишь их по порядку, в конце юнита ждёт тест.',
    'tour.learn.locked.title': 'Закрытые города',
    'tour.learn.locked.text': 'Уровни выше откроются, когда пройдёшь текущий.',
    'tour.lessons.tabs.title': 'Две вкладки',
    'tour.lessons.tabs.text':
      '«Онлайн» — занятия с преподавателем по расписанию. «Самостоятельно» — материалы курса твоего уровня, которые проходишь сам.',
    'tour.lessons.next.title': 'Ближайшее занятие',
    'tour.lessons.next.text':
      'Карточка сверху — следующий урок. Когда преподаватель начнёт занятие, отсюда же в него и заходишь.',
    'tour.lessons.calendar.title': 'Календарь',
