// К словарю языка вливаем строки из своих файлов: синхронизацию SAT с прототипом (SAT-SYNC-PLAN B13), документы и тарифы
function addLang(lang, table) {
  dict[lang] = Object.assign(table, SAT_SYNC_DICT[lang], LEGAL_AND_PRICING[lang === 'kk' ? 'kz' : lang])
}
addLang('ru', dict.ru)
for (const [lang, table] of Object.entries(EAGER_LANGS)) addLang(lang, table)

const known = (lang) => LANGS.some((l) => l.code === lang)

const loading = {}
// Загрузка один раз на язык. Сбой не держит экран: без словаря t() откатывается на русский.
function ensureLang(lang) {
  if (dict[lang]) return Promise.resolve()
  loading[lang] ??= loadLangTable(lang).then((table) => {
    if (table) addLang(lang, table)
  })
  return loading[lang]
}

function savedLang() {
  try {
    const saved = localStorage.getItem('lang')
    return saved && known(saved) ? saved : null
  } catch {
    return null
  }
}

// Сразу при импорте, не дожидаясь гидратации: тот, кто учится на казахском, иначе ждал бы словарь лишний шаг.
if (savedLang()) ensureLang(savedLang())

const I18nCtx = createContext(null)

export function I18nProvider({ children }) {
  const [lang, setLangState] = useState(() => savedLang() || 'ru')
  // Приехал ли словарь выбранного при входе языка. App держит спиннер, пока его нет: кабинет не мигает русским.
  const [langReady, setLangReady] = useState(() => !!dict[lang])
  useEffect(() => {
    if (!langReady) ensureLang(lang).finally(() => setLangReady(true))
    // eslint-disable-next-line react-hooks/exhaustive-deps -- только язык, с которым открылась страница
  }, [])

  // Последний выбранный язык: пока качался первый, человек мог нажать другой.
  const wanted = useRef(lang)
  const setLang = useCallback((l) => {
    wanted.current = l
    try {
      localStorage.setItem('lang', l)
    } catch (e) {
      /* ignore */
    }
    if (dict[l]) setLangState(l)
    // Переключаем, когда словарь приехал: иначе экран на это время стал бы русским.
    else ensureLang(l).finally(() => wanted.current === l && setLangState(l))
  }, [])

  // Язык — атрибутом на <html>: по нему казахский интерфейс целиком идёт на
  // Inter (src/kk-font.css). До гидратации его ставит UI_LANG_BOOT в layout.
  useEffect(() => applyUiLang(lang), [lang])

  const t = useCallback(
    (key, vars) => {
      let s = (dict[lang] && dict[lang][key]) ?? dict.ru[key] ?? key
      if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k])
      return s
    },
    // langReady: словарь языка, с которым открылась страница, приезжает уже после первого рендера
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [lang, langReady],
  )

  return <I18nCtx.Provider value={{ lang, setLang, t, langReady }}>{children}</I18nCtx.Provider>
}

export function useI18n() {
  return useContext(I18nCtx)
}
